"""Exact checks for the accompanying two-row CRT prefix result."""

from collections import defaultdict
from itertools import product


def crt_columns(m, n, rows, columns, capacities):
    period = m * n
    omega = [n * (row * pow(n, -1, m) % m) for row in rows]
    assert omega[0] < omega[1]
    cells = []
    for column, capacity in zip(columns, capacities, strict=True):
        nu = m * (column * pow(m, -1, n) % n)
        carry0, k0 = divmod(omega[0] + nu, period)
        carry1, k1 = divmod(omega[1] + nu, period)
        cells.append((capacity, k0, k1, carry0, carry1))
    return cells, omega[1] - omega[0], period


def graph_witness(cells, length, period, row0, carry, cuts, readings):
    groups = [[], []]
    for index, (capacity, k0, k1, carry0, carry1) in enumerate(cells):
        groups[carry1 - carry0].append((min(k0, k1), capacity, index))
    wrap_row0 = sum(c * carry1 for c, _, _, _, carry1 in cells) - carry
    totals = [row0 - wrap_row0, sum(c for _, c, _ in groups[1]) - wrap_row0]
    lengths = [length, period - length]
    signs = [-1, 1] if lengths[0] >= lengths[1] else [1, -1]
    edges = []
    offsets = []
    next_node = 1
    for columns, total, sign in zip(groups, totals, signs, strict=True):
        columns.sort()
        if not 0 <= total <= sum(c for _, c, _ in columns):
            return None
        endpoints = [(0, 0)]
        for _ in columns[1:]:
            endpoints.append((next_node, 0))
            next_node += 1
        if columns:
            endpoints.append((0, sign * total))
        offsets.append(endpoints)
        for (_, capacity, _), (old, old_shift), (new, new_shift) in zip(
            columns, endpoints[:-1], endpoints[1:], strict=True
        ):
            lower, upper = (0, capacity) if sign == 1 else (-capacity, 0)
            shift = new_shift - old_shift
            edges.extend(((old, new, upper - shift), (new, old, shift - lower)))

    for cut, reading in zip(cuts, readings, strict=True):
        fixed = sum(c for c, k0, k1, _, _ in cells if max(k0, k1) < cut)
        terms = {}
        for columns, endpoints, total, interval, sign in zip(
            groups, offsets, totals, lengths, signs, strict=True
        ):
            if not columns:
                continue
            active = [int(start < cut <= start + interval) for start, _, _ in columns]
            fixed += active[-1] * total
            for i, (left, right) in enumerate(zip(active, active[1:]), start=1):
                if left != right:
                    terms[endpoints[i][0]] = sign * (left - right)
        assert len(terms) <= 2
        assert len(terms) < 2 or sum(terms.values()) == 0
        rhs = reading - fixed
        if not terms:
            if rhs != 0:
                return None
            continue
        positive = next((node for node, value in terms.items() if value == 1), 0)
        negative = next((node for node, value in terms.items() if value == -1), 0)
        edges.extend(((negative, positive, rhs), (positive, negative, -rhs)))

    distance = [0] * next_node
    for _ in distance:
        changed = False
        for source, target, weight in edges:
            if distance[source] + weight < distance[target]:
                distance[target] = distance[source] + weight
                changed = True
        if not changed:
            break
    else:
        return None

    row = [0] * len(cells)
    for group, (columns, endpoints, sign) in enumerate(zip(groups, offsets, signs, strict=True)):
        for (_, capacity, index), (old, old_shift), (new, new_shift) in zip(
            columns, endpoints[:-1], endpoints[1:], strict=True
        ):
            mass = sign * (distance[new] + new_shift - distance[old] - old_shift)
            row[index] = mass if group == 0 else capacity - mass
    return tuple(row)


def read(cells, row, cuts):
    assert all(0 <= count <= cell[0] for count, cell in zip(row, cells, strict=True))
    carry = sum(
        count * e0 + (capacity - count) * e1
        for count, (capacity, _, _, e0, e1) in zip(row, cells, strict=True)
    )
    prefix = tuple(
        sum(
            count * (k0 < cut) + (capacity - count) * (k1 < cut)
            for count, (capacity, k0, k1, _, _) in zip(row, cells, strict=True)
        )
        for cut in cuts
    )
    return sum(row), carry, prefix


def validate_case(name, parameters, capacities, cuts):
    cells, length, period = crt_columns(*parameters, capacities)
    by_baseline = defaultdict(set)
    for row in product(*(range(c + 1) for c in capacities)):
        row0, carry, prefix = read(cells, row, cuts)
        by_baseline[row0, carry].add(prefix)
    mass = sum(capacities)
    checks = 0
    for row0, carry in product(range(mass + 1), repeat=2):
        actual = by_baseline[row0, carry]
        if actual:
            coordinate_ranges = [range(min(values), max(values) + 1) for values in zip(*actual)]
            queries = product(*coordinate_ranges)
        else:
            queries = [tuple(0 for _ in cuts)]
        for query in queries:
            row = graph_witness(cells, length, period, row0, carry, cuts, query)
            assert (row is not None) == (query in actual), (name, row0, carry, query)
            if row is not None:
                assert read(cells, row, cuts) == (row0, carry, query)
            checks += 1
    print(f"{name}: {sum(bool(fiber) for fiber in by_baseline.values())} nonempty baselines, {checks} joint queries checked")


def check_three_row_hole():
    omega, nu = (0, 5, 10), (0, 4, 8, 12)
    period = 4 * 5
    labels = [[divmod(a + b, period) for b in nu] for a in omega]
    assert [[k for _, k in row] for row in labels] == [
        [0, 4, 8, 12], [5, 9, 13, 17], [10, 14, 18, 2]
    ]
    cuts = (5, 9, 11, 18)
    image = {}
    for chosen_rows in product(range(3), repeat=4):
        if tuple(chosen_rows.count(row) for row in range(3)) != (1, 2, 1):
            continue
        cells = [labels[row][column] for column, row in enumerate(chosen_rows)]
        if sum(e for e, _ in cells) != 0:
            continue
        image[chosen_rows] = tuple(sum(k < h for _, k in cells) for h in cuts)
    left = image[(2, 1, 1, 0)]
    right = image[(1, 2, 0, 1)]
    midpoint = (0, 1, 2, 4)
    assert len(set(image.values())) == 9
    assert [a + b for a, b in zip(left, right)] == [2 * c for c in midpoint]
    assert midpoint not in image.values()
    print(f"three-row true-carry hole: cuts {cuts}, midpoint {midpoint}, 9 attainable vectors")


if __name__ == "__main__":
    gap = (3, 4, (0, 2), (0, 2, 1))
    capacities = (1, 1, 2)
    cells, _, _ = crt_columns(*gap, capacities)
    assert [(k0, k1) for _, k0, k1, _, _ in cells] == [(0, 8), (6, 2), (9, 5)]
    retained = []
    for row in product(*(range(c + 1) for c in capacities)):
        row0, carry, (prefix4, prefix8) = read(cells, row, (4, 8))
        if row0 == 2 and prefix4 == 1:
            retained.append((row, carry, prefix8))
    assert retained == [((0, 0, 2), 1, 1), ((1, 1, 0), 2, 4)]
    print("arbitrary-prefix witness (first row, true carry, C(8)):", retained)

    validate_case("gap witness with true carry", gap, capacities, (1, 4, 6, 8, 10))
    validate_case("N=871 six-cell support", (3, 5, (2, 1), (0, 1, 4)), (2, 3, 3), (2, 3, 5, 12, 15))
    validate_case("four-column support", (5, 4, (0, 3), (0, 1, 2, 3)), (1, 2, 1, 2), (0, 4, 7, 11, 16))
    validate_case("empty wrap group", (3, 4, (0, 2), (0, 3)), (2, 2), (0, 1, 4, 8, 12))
    validate_case("empty same-wrap group", (3, 4, (0, 2), (1, 2)), (2, 2), (0, 3, 6, 9, 12))
    check_three_row_hole()
